document.addEventListener("DOMContentLoaded", () => {
    const wrapper = document.querySelector(".wp-block-custom");
    const attributes = JSON.parse(wrapper.dataset.attributes);

    root.render(
        <div dangerouslySetInnerHTML={{ __html: attributes.icon?.svg }} />
    );
});

// Client-side verification:
const isSafeUrl = (url) => {
    try {
        const parsed = new URL(url, window.location.origin);
        return ['http:', 'https:'].includes(parsed.protocol);
    } catch {
        return false;
    }
};

$clean_attributes = array(
    'title' => sanitize_text_field( $attributes['title'] ?? '' ),
    'icon'  => wp_kses_post( $attributes['icon'] ?? '' ),
    'link'  => esc_url_raw( $attributes['link'] ?? '', array( 'http', 'https' ) ),
);
data-attributes="<?php echo esc_attr( wp_json_encode( $clean_attributes ) ); ?>"
